function y({registerIndicator:c,nulls:u}){c({id:"oa-adr",name:"Average Daily Range (ADR)",category:"Volatility",placement:"pane",inputs:[{key:"length",type:"number",label:"Length",default:14,min:1,max:500,step:1,tooltip:"Number of bars to average the daily range over"},{key:"method",type:"number",label:"Method",default:1,min:1,max:3,step:1,tooltip:"1 = SMA, 2 = EMA, 3 = WMA"}],plots:[{key:"adr",type:"line",title:"ADR",style:{color:"#ffeb3b",lineWidth:2}}],calc(h,s){const a=Math.max(1,Math.min(500,Math.floor(Number(s.length)||14))),d=Math.max(1,Math.min(3,Math.floor(Number(s.method)||1))),i=h.length,m=new Array(i).fill(NaN),r=new Array(i);for(let l=0;l<i;l++){const t=h[l].high-h[l].low;r[l]=Number.isFinite(t)?t:0}if(d===1){let l=0,t=0;for(let e=0;e<i;e++)e-a>=0&&(l-=r[e-a],t-=1),l+=r[e],t+=1,m[e]=t>0?l/t:r[e]}else if(d===2){const t=1/a;let e=0,n=1;for(let o=0;o<i;o++)e=(e*(a-1)+r[o])/a,n=(1-t)*n,m[o]=n>1e-10?e/(1-n):e}else{const l=a*(a+1)/2;for(let t=0;t<i;t++){let e=0,n=a;for(let o=0;o<a;o++){const f=t-o;e+=(f>=0?r[f]:0)*n,n-=1}m[t]=l>0?e/l:NaN}}return{adr:u(m)}}})}export{y as default};
